const metrics = $input.first().json;

const THRESHOLDS = {
  error_rate_pct: 5,       // alert if >5% of calls errored
  p95_latency_ms: 8000,   // alert if p95 latency >8s
  low_confidence_pct: 20, // alert if >20% of outputs <0.8 confidence
  zero_calls: true        // alert if no calls in window (possible pipeline failure)
};

const alerts = [];

for (const agent of metrics.agents) {
  if (agent.total_calls === 0 && THRESHOLDS.zero_calls) {
    alerts.push({
      agent: agent.name,
      severity: 'warning',
      type: 'no_traffic',
      message: `No calls recorded in the last 15 minutes — pipeline may be down`
    });
  }
  if (agent.error_rate_pct > THRESHOLDS.error_rate_pct) {
    alerts.push({
      agent: agent.name,
      severity: agent.error_rate_pct > 20 ? 'critical' : 'warning',
      type: 'high_error_rate',
      message: `Error rate ${agent.error_rate_pct}% exceeds threshold ${THRESHOLDS.error_rate_pct}%`,
      value: agent.error_rate_pct
    });
  }
  if (agent.p95_latency_ms > THRESHOLDS.p95_latency_ms) {
    alerts.push({
      agent: agent.name,
      severity: 'warning',
      type: 'high_latency',
      message: `P95 latency ${agent.p95_latency_ms}ms exceeds threshold ${THRESHOLDS.p95_latency_ms}ms`,
      value: agent.p95_latency_ms
    });
  }
  if (agent.low_confidence_pct > THRESHOLDS.low_confidence_pct) {
    alerts.push({
      agent: agent.name,
      severity: 'warning',
      type: 'low_confidence_drift',
      message: `${agent.low_confidence_pct}% of outputs below confidence threshold — possible prompt degradation`,
      value: agent.low_confidence_pct
    });
  }
}

return [{
  json: {
    checked_at: new Date().toISOString(),
    window_minutes: 15,
    agent_count: metrics.agents.length,
    alert_count: alerts.length,
    alerts,
    metrics: metrics.agents
  }
}];

const { alerts, checked_at, window_minutes } = $input.first().json;

const hasCritical = alerts.some(a => a.severity === 'critical');
const emoji = hasCritical ? ':rotating_light:' : ':warning:';
const header = hasCritical ? '*CRITICAL — Agent Pipeline Alert*' : '*Agent Monitor Warning*';

const alertLines = alerts.map(a =>
  `• *[${a.severity.toUpperCase()}]* ${a.agent}: ${a.message}`
).join('\n');

return [{
  json: {
    text: `${emoji} ${header}`,
    blocks: [
      {
        type: 'header',
        text: { type: 'plain_text', text: `${emoji} ${hasCritical ? 'CRITICAL' : 'Warning'}: Agent Pipeline` }
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `*${alerts.length} alert(s)* detected in the last ${window_minutes} minutes:\n\n${alertLines}`
        }
      },
      {
        type: 'context',
        elements: [{ type: 'mrkdwn', text: `Checked at ${checked_at}` }]
      }
    ]
  }
}];

// Log all-clear tick to your metrics store
// Replace with Supabase insert, HTTP POST to your logging endpoint, etc.
console.log(JSON.stringify({
  event: 'monitor_check',
  checked_at: $json.checked_at,
  alert_count: $json.alert_count,
  agent_count: $json.agent_count
}));
return $input.all();
